use super::*;
use std::collections::VecDeque;
#[derive(Default)]struct Fake{responses:Mutex<VecDeque<Result<Value>>>,calls:Mutex<Vec<Value>>}
impl Transport for Fake{fn request(&self,base:&str,path:&str,token:Option<&str>,body:Option<Value>,query:&[(String,String)])->Result<Value>{self.calls.lock().unwrap().push(json!({"base":base,"path":path,"token":token,"body":body,"query":query}));self.responses.lock().unwrap().pop_front().expect("unexpected network request")}}
fn fixture()->(WeixinLab,Arc<Fake>,PathBuf){let dir=std::env::temp_dir().join(format!("floatboard-weixin-lab-{}",uuid::Uuid::new_v4()));let fake=Arc::new(Fake::default());let lab=WeixinLab::build(dir.clone(),fake.clone(),false).unwrap();(lab,fake,dir)}
fn push(f:&Fake,v:Value){f.responses.lock().unwrap().push_back(Ok(v));}
fn account()->Account{Account{token:"secret-token".into(),bot_id:"secret-bot".into(),login_user:"secret-user".into(),base:BASE.into(),..Account::default()}}
fn message(user:&str,bot:&str,text:&str)->Value{json!({"from_user_id":user,"to_user_id":bot,"message_type":1,"context_token":"secret-context","item_list":[{"type":1,"text_item":{"text":text}}]})}
#[test]fn strict_hosts_and_no_credential_urls(){assert_eq!(validate_base(BASE).unwrap(),BASE);assert!(validate_base("https://edge.weixin.qq.com/").is_ok());for bad in ["http://ilinkai.weixin.qq.com","https://weixin.qq.com.evil.org","https://evilweixin.qq.com","https://127.0.0.1","https://ilinkai.weixin.qq.com:444","https://u:p@ilinkai.weixin.qq.com","https://ilinkai.weixin.qq.com/path","https://ilinkai.weixin.qq.com?token=x","https://ilinkai.weixin.qq.com#x","https://ilinkai.weixin.qq.com\\@evil.org"]{assert!(validate_base(bad).is_err(),"{bad}");}}
#[test]fn offline_restore_dpapi_and_explicit_confirmation(){let(lab,fake,dir)=fixture();assert!(fake.calls.lock().unwrap().is_empty());{let mut s=lab.inner.state.lock().unwrap();let mut a=account();a.recipient=a.login_user.clone();a.context="secret-context".into();a.cursor="secret-cursor".into();s.account=Some(a);persist(&lab.inner,&s).unwrap();}let bytes=fs::read(dir.join("account.dpapi")).unwrap();for secret in ["secret-token","secret-user","secret-context","secret-cursor"]{assert!(!bytes.windows(secret.len()).any(|b|b==secret.as_bytes()));}drop(lab);let restored=WeixinLab::build(dir.clone(),fake.clone(),false).unwrap();let snap=restored.call("snapshot",&json!({})).unwrap();assert_eq!(snap["status"],"restored");assert_eq!(snap["active"],false);assert!(!snap.to_string().contains("secret-"));step(&restored.inner);assert!(fake.calls.lock().unwrap().is_empty());assert!(restored.call("send_test",&json!({})).is_err());push(&fake,json!({"ret":0}));restored.call("send_test",&json!({"confirmed":true})).unwrap();step(&restored.inner);assert_eq!(restored.call("snapshot",&json!({})).unwrap()["last_test_status"],"accepted");assert_eq!(fake.calls.lock().unwrap().len(),1);restored.call("disconnect",&json!({})).unwrap();drop(restored);let clean=WeixinLab::build(dir.clone(),fake,false).unwrap();assert_eq!(clean.call("snapshot",&json!({})).unwrap()["logged_in"],false);drop(clean);fs::remove_dir_all(dir).unwrap();}
#[test]fn fake_login_verify_bind_sender_and_text_test(){let(lab,fake,dir)=fixture();push(&fake,json!({"qrcode":"qr-id","qrcode_img_content":"https://weixin.qq.com/qr-value"}));lab.call("start_login",&json!({})).unwrap();step(&lab.inner);assert_eq!(lab.call("snapshot",&json!({})).unwrap()["status"],"waiting_scan");push(&fake,json!({"status":"need_verifycode"}));step(&lab.inner);assert!(lab.call("verify_code",&json!({"code":"abc"})).is_err());lab.call("verify_code",&json!({"code":"123456"})).unwrap();push(&fake,json!({"status":"confirmed","bot_token":"secret-token","ilink_bot_id":"secret-bot","ilink_user_id":"secret-user","baseurl":BASE}));step(&lab.inner);assert_eq!(lab.call("snapshot",&json!({})).unwrap()["status"],"logged_in");assert!(lab.call("send_test",&json!({"confirmed":true})).is_err());let code=lab.call("start_binding",&json!({})).unwrap()["binding_code"].as_str().unwrap().to_owned();push(&fake,json!({"ret":0,"get_updates_buf":"cursor-one","msgs":[message("attacker","secret-bot",&code),message("secret-user","wrong-bot",&code),message("secret-user","secret-bot","wrong")] }));step(&lab.inner);assert_eq!(lab.call("snapshot",&json!({})).unwrap()["bound"],false);push(&fake,json!({"ret":0,"get_updates_buf":"cursor-two","msgs":[message("secret-user","secret-bot",&code)]}));step(&lab.inner);let snap=lab.call("snapshot",&json!({})).unwrap();assert_eq!(snap["bound"],true);assert_eq!(snap["binding_code"],"");assert!(!snap.to_string().contains("secret-"));push(&fake,json!({"ret":0}));lab.call("send_test",&json!({"confirmed":true})).unwrap();step(&lab.inner);let calls=fake.calls.lock().unwrap();assert_eq!(calls.last().unwrap()["path"],"ilink/bot/sendmessage");assert_eq!(calls.last().unwrap()["body"]["msg"]["to_user_id"],"secret-user");assert_eq!(calls.last().unwrap()["body"]["msg"]["context_token"],"secret-context");assert!(!calls.last().unwrap().to_string().contains("task_id"));drop(calls);drop(lab);fs::remove_dir_all(dir).unwrap();}
#[test]fn stale_token_pauses_without_retry_or_secret_echo(){let(lab,fake,dir)=fixture();lab.inner.state.lock().unwrap().account=Some(account());lab.call("resume",&json!({})).unwrap();push(&fake,json!({"ret":-14,"errmsg":"secret-token secret-user"}));step(&lab.inner);let snap=lab.call("snapshot",&json!({})).unwrap();assert_eq!(snap["status"],"paused");assert!(!snap.to_string().contains("secret-"));assert!(snap["pause_until"].as_f64().unwrap()>now()+3500.);assert!(lab.call("resume",&json!({})).is_err());step(&lab.inner);assert_eq!(fake.calls.lock().unwrap().len(),1);drop(lab);fs::remove_dir_all(dir).unwrap();}
#[test]fn cancellation_blocks_stale_qr_and_expired_binding_cannot_bind(){let(lab,fake,dir)=fixture();lab.call("start_login",&json!({})).unwrap();lab.call("cancel_login",&json!({})).unwrap();step(&lab.inner);assert!(fake.calls.lock().unwrap().is_empty());{let mut s=lab.inner.state.lock().unwrap();s.account=Some(account());s.bind_code="绑定 expired-code".into();s.bind_expires=now()-1.;apply_updates(&mut s,&json!({"msgs":[message("secret-user","secret-bot","绑定 expired-code")]})).unwrap();assert!(s.account.as_ref().unwrap().recipient.is_empty());}assert!(WeixinLab::build(dir.clone(),fake,false).is_err());drop(lab);fs::remove_dir_all(dir).unwrap();}
#[test]fn in_flight_login_cancel_drops_delayed_credentials(){
 struct Delayed{entered:std::sync::mpsc::Sender<()>,release:Mutex<std::sync::mpsc::Receiver<()>>}
 impl Transport for Delayed{fn request(&self,_:&str,_:&str,_:Option<&str>,_:Option<Value>,_:&[(String,String)])->Result<Value>{self.entered.send(()).unwrap();self.release.lock().unwrap().recv().unwrap();Ok(json!({"qrcode":"stale-secret-qr","qrcode_img_content":"stale-secret-content"}))}}
 let(entered,ready)=std::sync::mpsc::channel();let(release,wait)=std::sync::mpsc::channel();let dir=std::env::temp_dir().join(format!("floatboard-weixin-cancel-{}",uuid::Uuid::new_v4()));let lab=WeixinLab::build(dir.clone(),Arc::new(Delayed{entered,release:Mutex::new(wait)}),false).unwrap();lab.call("start_login",&json!({})).unwrap();let i=lab.inner.clone();let worker=std::thread::spawn(move||step(&i));ready.recv_timeout(Duration::from_secs(3)).unwrap();lab.call("cancel_login",&json!({})).unwrap();release.send(()).unwrap();worker.join().unwrap();let snapshot=lab.call("snapshot",&json!({})).unwrap();assert_eq!(snapshot["status"],"disconnected");assert!(!snapshot.to_string().contains("stale-secret"));drop(lab);fs::remove_dir_all(dir).unwrap();
}
#[test]fn send_ack_optional_ret_and_unknown_are_not_false_failures(){let mut s=State{account:Some(account()),..State::default()};for ack in [json!({"message_id":"18446744073709551615"}),json!({"message_id":123}),json!({"ret":0})]{checked(&ack).unwrap();apply(&mut s,&Work::Send,&ack).unwrap();assert_eq!(s.last_test,"accepted");}for ack in [json!({}),json!({"message_id":"bad"}),json!({"message_id":0}),json!({"message_id":"000"})]{checked(&ack).unwrap();apply(&mut s,&Work::Send,&ack).unwrap();assert_eq!(s.last_test,"unknown");assert_eq!(s.status,"bound");}assert!(checked(&json!({"ret":3,"message_id":"1"})).is_err());assert!(checked(&json!({"ret":0,"errcode":4,"errmsg":"sensitive"})).unwrap_err().find("sensitive").is_none());}
